.att3-panel{background:#fff;border:1px solid var(--line);border-radius:12px;overflow:hidden}.att3-tools{padding:10px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:7px;flex-wrap:wrap}.att3-search{position:relative;flex:1;min-width:220px}.att3-search input{height:35px;width:100%;border:1px solid var(--line);border-radius:8px;padding:0 32px 0 10px;font-size:.77rem}.att3-search i{position:absolute;right:11px;top:10px;color:#98a2b3;font-size:.72rem}.att3-tools select{height:35px;border:1px solid var(--line);border-radius:8px;padding:0 8px;font-size:.75rem;color:#475467;background:#fff;min-width:135px}.selection-bar{display:none;align-items:center;gap:7px;padding:8px 10px;background:#f1f6fc;border-bottom:1px solid #dbe7f5}.selection-bar.show{display:flex}.selection-count{font-size:.74rem;font-weight:800;color:var(--brand);margin-left:auto}.bulk-btn{height:30px;border:0;border-radius:7px;padding:0 9px;font-size:.7rem;font-weight:750;display:inline-flex;align-items:center;gap:5px;cursor:pointer}.bulk-in{background:#dff3e7;color:#176b40}.bulk-out{background:#fbe1e5;color:#a82e3b}.bulk-leave{background:#fff0bd;color:#785d00}.bulk-absent{background:#eceff3;color:#475467}.bulk-mode{height:30px;border:1px solid #d7e0eb;border-radius:7px;background:#fff;font-size:.7rem;padding:0 7px}
.att3-table{width:100%;border-collapse:separate;border-spacing:0}.att3-table th{height:38px;background:#fafbfc;border-bottom:1px solid var(--line);font-size:.67rem;font-weight:800;color:#667085;text-align:right;padding:0 12px;white-space:nowrap}.att3-table td{height:54px;border-bottom:1px solid #f0f1f3;padding:7px 12px;font-size:.76rem;color:#344054;vertical-align:middle}.att3-table tbody tr:hover{background:#fbfcfe}.att3-table tbody tr:last-child td{border-bottom:0}.check-col{width:38px;text-align:center!important}.row-check,.head-check{width:15px;height:15px;accent-color:var(--brand);cursor:pointer}.person{display:flex;align-items:center;gap:8px;min-width:185px}.person-avatar{width:31px;height:31px;border-radius:50%;background:#edf3fb;color:var(--brand);display:flex;align-items:center;justify-content:center;font-size:.7rem;font-weight:800;flex:none}.person-name{font-size:.77rem;font-weight:800;color:#273444}.person-meta{font-size:.65rem;color:#98a2b3;margin-top:1px}.dept3{color:#667085;font-size:.72rem}.time3{font-variant-numeric:tabular-nums;font-weight:700;color:#344054}.time3.empty{font-weight:500;color:#adb5bd}.mode3{font-size:.67rem;font-weight:700;padding:3px 7px;background:#f1f3f5;border-radius:5px;color:#596579}.status3{display:inline-flex;align-items:center;gap:4px;border-radius:15px;padding:3px 8px;font-size:.67rem;font-weight:800}.status3.p{background:#eaf7ef;color:#167447}.status3.l{background:#fff5d7;color:#8a6700}.status3.a{background:#fdebed;color:#b42331}.status3.lv{background:#eaf5fb;color:#126c8e}.status3.e{background:#eef0f3;color:#667085}.row-action{display:flex;justify-content:flex-end;gap:5px;align-items:center}.row-action select{height:29px;border:1px solid var(--line);border-radius:6px;font-size:.68rem;padding:0 5px;max-width:95px}.row-btn{height:29px;border:0;border-radius:6px;padding:0 8px;font-size:.68rem;font-weight:750;cursor:pointer}.row-in{background:#eaf7ef;color:#167447}.row-out{background:#fdebed;color:#b42331}.row-leave{background:#fff4cf;color:#7b5c00}.done{font-size:.68rem;color:#98a2b3;display:inline-flex;align-items:center;gap:4px}.empty3{text-align:center!important;padding:35px!important;color:#98a2b3}
@media(max-width:950px){.att3{padding:16px}.att3-kpis{grid-template-columns:repeat(2,1fr)}.att3-table{min-width:920px}.att3-panel{overflow-x:auto}.att3-tools,.selection-bar{position:relative}}@media(max-width:600px){.att3-head{align-items:stretch;flex-direction:column}.att3-kpis{grid-template-columns:1fr 1fr}}
