<?php if($message): ?><div class="alert alert-<?php echo $msg_type==='error'?'danger':'success'; ?> py-2 px-3 mb-3" style="border-radius:8px;font-size:.78rem"><?php echo e($message); ?><button type="button" class="btn-close"></button></div><?php endif; ?>
<div class="att3-kpis"><div class="kpi p"><div><div class="kpi-label"><?php echo e(t('hr.present')); ?></div><div class="kpi-num"><?php echo $stats['present']; ?></div></div><div class="kpi-mark"><i class="fas fa-check"></i></div></div><div class="kpi l"><div><div class="kpi-label"><?php echo e(t('hr.late')); ?></div><div class="kpi-num"><?php echo $stats['late']; ?></div></div><div class="kpi-mark"><i class="fas fa-clock"></i></div></div><div class="kpi a"><div><div class="kpi-label"><?php echo e(t('hr.absent')); ?></div><div class="kpi-num"><?php echo $stats['absent']; ?></div></div><div class="kpi-mark"><i class="fas fa-user-xmark"></i></div></div><div class="kpi lv"><div><div class="kpi-label"><?php echo e(t('hr.on_leave')); ?></div><div class="kpi-num"><?php echo $stats['on_leave']; ?></div></div><div class="kpi-mark"><i class="fas fa-calendar-day"></i></div></div></div>
<div class="att3-panel">
<div class="att3-tools"><div class="att3-search"><i class="fas fa-search"></i><input id="attSearch" type="search" placeholder="البحث باسم الموظف..." autocomplete="off"></div><select id="attDept"><option value="">كل الأقسام</option><?php $deps=[];foreach($employees as $e){if(!empty($e['dept_name']))$deps[$e['department_id']]=$e['dept_name'];}foreach($deps as $d): ?><option value="<?php echo htmlspecialchars($d); ?>"><?php echo htmlspecialchars($d); ?></option><?php endforeach; ?></select><select id="attStatus"><option value="">كل الحالات</option><option value="present"><?php echo e(t('hr.present')); ?></option><option value="late"><?php echo e(t('hr.late')); ?></option><option value="absent"><?php echo e(t('hr.absent')); ?></option><option value="on_leave"><?php echo e(t('hr.on_leave')); ?></option></select></div>
<form method="POST" id="bulkForm"><input type="hidden" name="selected_date" value="<?php echo htmlspecialchars($selected_date); ?>"><div class="selection-bar" id="selectionBar"><select name="bulk_work_mode" class="bulk-mode"><option value="remote"><?php echo e(t('hr.work_mode_remote')); ?></option><option value="onsite"><?php echo e(t('hr.work_mode_onsite')); ?></option><option value="hybrid"><?php echo e(t('hr.work_mode_hybrid')); ?></option></select><button type="submit" name="action" value="bulk_check_in" class="bulk-btn bulk-in"><i class="fas fa-right-to-bracket"></i> تسجيل حضور</button><button type="submit" name="action" value="bulk_check_out" class="bulk-btn bulk-out"><i class="fas fa-right-from-bracket"></i> تسجيل انصراف</button><button type="submit" name="action" value="bulk_leave" class="bulk-btn bulk-leave"><i class="fas fa-calendar-check"></i> إجازة</button><button type="submit" name="action" value="bulk_absent" class="bulk-btn bulk-absent"><i class="fas fa-user-xmark"></i> غياب</button><span class="selection-count" id="selectionCount">0 محدد</span></div>
<div class="table-responsive"><table class="att3-table" id="attTable"><thead><tr><th class="check-col"><input class="head-check" id="selectAll" type="checkbox" title="تحديد الكل"></th><th><?php echo e(t('hr.employee')); ?></th><th><?php echo e(t('groups.group')); ?></th><th><?php echo e(t('hr.check_in')); ?></th><th><?php echo e(t('hr.check_out')); ?></th><th>النمط</th><th><?php echo e(t('common.status')); ?></th><th class="text-end"><?php echo e(t('common.actions')); ?></th></tr></thead><tbody>
<?php if(empty($employees)): ?><tr><td colspan="8" class="empty3">لا يوجد موظفون نشطون.</td></tr><?php else: foreach($employees as $emp): $att=$attendance_records[$emp['id']]??null;$status=$att['status']??'absent';$work_mode=$att['work_mode']??'';$initial=mb_substr(trim((string)$emp['full_name']),0,1,'UTF-8');$sc=['present'=>'p','late'=>'l','absent'=>'a','on_leave'=>'lv','half_day'=>'e'];$si=['present'=>'fa-check','late'=>'fa-clock','absent'=>'fa-user-xmark','on_leave'=>'fa-calendar-check','half_day'=>'fa-minus'];$sl=['present'=>'hr.present','late'=>'hr.late','absent'=>'hr.absent','on_leave'=>'hr.on_leave','half_day'=>'hr.half_day']; ?>
<tr data-name="<?php echo htmlspecialchars(mb_strtolower((string)$emp['full_name'],'UTF-8')); ?>" data-dept="<?php echo htmlspecialchars((string)($emp['dept_name']??'')); ?>" data-status="<?php echo htmlspecialchars($status); ?>"><td class="check-col"><input class="row-check" type="checkbox" name="employee_ids[]" value="<?php echo (int)$emp['id']; ?>"></td><td><div class="person"><div class="person-avatar"><?php echo htmlspecialchars($initial); ?></div><div><div class="person-name"><?php echo htmlspecialchars($emp['full_name']); ?></div><div class="person-meta">ID #<?php echo (int)$emp['id']; ?></div></div></div></td><td class="dept3"><?php echo htmlspecialchars($emp['dept_name']??'-'); ?></td><td><span class="time3 <?php echo (!$att||!$att['check_in'])?'empty':''; ?>"><?php echo ($att&&$att['check_in'])?substr($att['check_in'],0,5):'--:--'; ?></span></td><td><span class="time3 <?php echo (!$att||!$att['check_out'])?'empty':''; ?>"><?php echo ($att&&$att['check_out'])?substr($att['check_out'],0,5):'--:--'; ?></span></td><td><span class="mode3"><?php $modes=['remote'=>'hr.work_mode_remote','onsite'=>'hr.work_mode_onsite','hybrid'=>'hr.work_mode_hybrid'];echo $att?e(t($modes[$work_mode]??'hr.work_mode_remote')):'—'; ?></span></td><td><span class="status3 <?php echo $sc[$status]??'e'; ?>"><i class="fas <?php echo $si[$status]??'fa-minus'; ?>"></i><?php echo e(t($sl[$status]??'common.status')); ?></span></td><td class="text-end"><div class="row-action"><?php if(!$att||!$att['check_in']): ?><form method="POST" class="m-0"><input type="hidden" name="action" value="check_in"><input type="hidden" name="employee_id" value="<?php echo $emp['id']; ?>"><select name="work_mode"><option value="remote"><?php echo e(t('hr.work_mode_remote')); ?></option><option value="onsite"><?php echo e(t('hr.work_mode_onsite')); ?></option></select><button class="row-btn row-in" type="submit"><i class="fas fa-right-to-bracket"></i></button></form><?php elseif(!$att['check_out']): ?><form method="POST" class="m-0"><input type="hidden" name="action" value="check_out"><input type="hidden" name="employee_id" value="<?php echo $emp['id']; ?>"><button class="row-btn row-out" type="submit" title="<?php echo e(t('hr.check_out')); ?>"><i class="fas fa-right-from-bracket"></i></button></form><?php else: ?><span class="done"><i class="fas fa-circle-check"></i><?php echo e(t('hr.complete')); ?></span><?php endif; ?><?php if(!$att||$att['status']==='absent'): ?><form method="POST" class="m-0"><input type="hidden" name="action" value="mark_leave"><input type="hidden" name="employee_id" value="<?php echo $emp['id']; ?>"><button class="row-btn row-leave" type="submit" title="<?php echo e(t('hr.leave')); ?>"><i class="fas fa-calendar-check"></i></button></form><?php endif; ?></div></td></tr>
<?php endforeach; endif; ?></tbody></table></div></form></div></div>
<script>
document.addEventListener('DOMContentLoaded',function(){const table=document.getElementById('attTable'),all=document.getElementById('selectAll'),bar=document.getElementById('selectionBar'),count=document.getElementById('selectionCount'),search=document.getElementById('attSearch'),dept=document.getElementById('attDept'),status=document.getElementById('attStatus'),form=document.getElementById('bulkForm');function rows(){return Array.from(table.querySelectorAll('tbody tr[data-name]'));}function checks(){return rows().filter(r=>r.style.display!=='none').map(r=>r.querySelector('.row-check')).filter(Boolean)}function refresh(){const visible=checks(),selected=visible.filter(c=>c.checked);count.textContent=selected.length+' محدد';bar.classList.toggle('show',selected.length>0);all.checked=visible.length>0&&selected.length===visible.length;all.indeterminate=selected.length>0&&selected.length<visible.length;}function filter(){const q=(search.value||'').trim().toLocaleLowerCase();rows().forEach(r=>{r.style.display=(!q||r.dataset.name.includes(q))&&(!dept.value||r.dataset.dept===dept.value)&&(!status.value||r.dataset.status===status.value)?'':'none';});refresh();}all.addEventListener('change',function(){checks().forEach(c=>c.checked=all.checked);refresh();});table.addEventListener('change',function(e){if(e.target.classList.contains('row-check'))refresh();});search.addEventListener('input',filter);dept.addEventListener('change',filter);status.addEventListener('change',filter);form.addEventListener('submit',function(e){if(!checks().some(c=>c.checked)){e.preventDefault();alert('يرجى تحديد موظف واحد على الأقل.');}});});
</script>
